/*
 * arch/x86_64/cpu/idt_stubs.S
 *
 * One entry stub per vector (all 256), GENERATED by a macro loop
 * instead of being hand-written. Same idea as Linux's
 * arch/x86/entry/entry_64.S: each stub pushes the error code (real
 * or dummy) and the vector number, then all stubs converge on
 * isr_common, which saves the GPRs and calls the C dispatcher.
 *
 * Stack layout at the moment the CPU delivered the interrupt
 * (low -> high address):
 *
 *   SS, RSP, RFLAGS, CS, RIP, [error_code]
 *
 * then our stub pushes: [dummy error_code], vector
 * and isr_common pushes the 15 general purpose registers.
 */

.code64

/* Alternate macro mode: lets us splice the VALUE of a symbol into
 * a macro argument (%expr) instead of its literal text. Required
 * by the generator below to build labels like .Lisr_stub_17. */
.altmacro

.section .text

/* Common entry for every interrupt/exception.
 * On entry: [rsp+8] = vector, [rsp] = error code. */
isr_common:
    pushq %rax
    pushq %rbx
    pushq %rcx
    pushq %rdx
    pushq %rsi
    pushq %rdi
    pushq %rbp
    pushq %r8
    pushq %r9
    pushq %r10
    pushq %r11
    pushq %r12
    pushq %r13
    pushq %r14
    pushq %r15

    /* arg1 (rdi) = struct trap_frame * == current rsp */
    movq %rsp, %rdi
    call interrupt_handler

    /* Exceptions panic and never return here. IRQs DO return:
     * restore the GPRs, drop vector+error code, and iretq back
     * to whatever was interrupted. */
    popq %r15
    popq %r14
    popq %r13
    popq %r12
    popq %r11
    popq %r10
    popq %r9
    popq %r8
    popq %rbp
    popq %rdi
    popq %rsi
    popq %rdx
    popq %rcx
    popq %rbx
    popq %rax
    addq $16, %rsp          /* drop vector + error code */
    iretq

/* One stub. \num is the vector; \has_error is 1 if the CPU pushes
 * an error code for this vector (8, 10-14, 17, 21), 0 otherwise -
 * in which case we push a dummy 0 so the frame is always uniform. */
.macro isr_stub num, has_error
.Lisr_stub_\num:
    .if \has_error == 0
    pushq $0                /* dummy error code */
    .endif
    pushq $\num             /* vector number */
    jmp isr_common
.endm

/* Helper that emits one .quad table entry. Needed because %stub_i
 * can only be evaluated when it is a macro ARGUMENT. */
.macro stub_tbl_entry n
    .quad .Lisr_stub_\n
.endm

/* Generate stubs for all 256 vectors. The .set/.rept/.if combo is
 * the assembler's "for loop": __isr_loop_i runs 0..255, and on the
 * five error-code vectors we emit the real-error-code variant.
 * (The .L prefix keeps the counter symbol local.) */
.set __isr_loop_i, 0
.rept 256
    .if (__isr_loop_i == 8 || (__isr_loop_i >= 10 && __isr_loop_i <= 14) || __isr_loop_i == 17 || __isr_loop_i == 21)
        isr_stub %__isr_loop_i, 1
    .else
        isr_stub %__isr_loop_i, 0
    .endif
    .set __isr_loop_i, __isr_loop_i + 1
.endr

/* Address table used by idt_init() to fill the IDT gates */
.section .rodata
.global isr_stub_table
isr_stub_table:
.set __isr_loop_i, 0
.rept 256
    stub_tbl_entry %__isr_loop_i
    .set __isr_loop_i, __isr_loop_i + 1
.endr
